/* A página prioriza gráficos; valores e investigações aparecem por interação. */
(() => {
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=v=>Number(v).toLocaleString('pt-BR',{maximumFractionDigits:2});
 const time=v=>new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
 const narrow=()=>matchMedia('(max-width:650px)').matches;
 let parameterKey='',lot='',comparisonPage=1,scopeKey='',charts=new Map();
 const chartEmpty=text=>`<div class="analysis-empty">${esc(text)}</div>`;
 const tipAttrs=(text,point)=>`data-analysis-tip="${esc(text)}" data-analysis-point="${esc(point)}"`;
 const legend=series=>`<div class="analysis-legend">${series.map((s,i)=>`<span><i class="analysis-key analysis-key-${s.color??i}"></i>${esc(s.label)}</span>`).join('')}</div>`;
 function lineChart(series,labels,{id,limits=null,times=null,unit='peças',details=[],evidence=[],empty='Sem apontamentos nos filtros selecionados.'}={}) {
  const values=series.flatMap(s=>s.values.filter(Number.isFinite));if(!values.length)return chartEmpty(empty);
  let low=Math.min(...values,...(limits||[])),high=Math.max(...values,...(limits||[]));
  const spread=high-low||Math.max(1,Math.abs(high)*.05);low=limits?low-spread*.08:Math.min(0,low);high+=spread*.08;
  const rough=(high-low)/4,magnitude=10**Math.floor(Math.log10(rough)),step=[1,2,5,10].find(n=>n*magnitude>=rough)*magnitude;
  low=Math.floor(low/step)*step;high=Math.ceil(high/step)*step;if(unit==='%')high=Math.min(100,high);
  const mobile=narrow(),w=mobile?380:id==='parameter'?1000:640,h=mobile?250:270,left=mobile?48:58,right=20,top=20,bottom=44;
  const x=i=>times&&times.at(-1)>times[0]?left+(times[i]-times[0])/(times.at(-1)-times[0])*(w-left-right):left+(labels.length===1?.5:i/(labels.length-1))*(w-left-right);
  const y=v=>top+(high-v)/(high-low)*(h-top-bottom);
  const axes=Array.from({length:Math.floor((high-low)/step)+1},(_,i)=>{const v=low+step*i;return `<line class="analysis-gridline" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${esc(num(v))}${unit==='%'?'%':''}</text>`;}).join('');
  const labelStep=Math.max(1,Math.ceil(labels.length/(mobile?3:5))),spacing=mobile?85:110;let lastTick=-Infinity;
  const ticks=labels.map((label,i)=>{const final=i===labels.length-1,position=x(i);if(!final&&(i%labelStep!==0||position-lastTick<spacing||x(labels.length-1)-position<spacing))return '';lastTick=position;return `<text x="${position}" y="${h-14}" text-anchor="${final?'end':i===0?'start':'middle'}">${esc(label.replace(' · parcial','*'))}</text>`;}).join('');
  const band=limits?`<rect class="analysis-band" x="${left}" y="${y(limits[1])}" width="${w-left-right}" height="${y(limits[0])-y(limits[1])}"/><path class="analysis-limit" d="M${left},${y(limits[0])} H${w-right} M${left},${y(limits[1])} H${w-right}"/>`:'';
  const paths=series.map((s,k)=>{let open=false;const color=s.color??k,d=s.values.map((v,i)=>{if(!Number.isFinite(v)){open=false;return '';}const command=open?'L':'M';open=true;return command+x(i)+','+y(v);}).join(' ');const first=s.values.findIndex(Number.isFinite);
   return `<path class="analysis-series analysis-series-${color}" d="${d}"/>${s.values.map((v,i)=>{if(!Number.isFinite(v))return '';const deviates=limits&&(v<limits[0]||v>limits[1]),ref=deviates?evidence[i]:null,text=`${labels[i]}\n${s.label}: ${num(v)} ${unit}${details[i]?'\n'+details[i]:''}${ref?'\nFora da faixa · clique ou pressione Enter para investigar.':''}`;
    return `<g class="analysis-target" ${tipAttrs(text,id==='parameter'&&evidence[i]?id+':'+evidence[i].id+':'+evidence[i].key:id+':'+k+':'+i)} role="button" tabindex="${i===first?'0':'-1'}" aria-label="${esc(text.replaceAll('\n','. '))}" ${ref?`data-analysis-evidence="${esc(ref.id)}" data-analysis-key="${esc(ref.key)}"`:''}><circle class="analysis-hit" cx="${x(i)}" cy="${y(v)}" r="12"/><circle class="analysis-dot analysis-dot-${color} ${deviates?'is-deviation':''}" cx="${x(i)}" cy="${y(v)}" r="${labels.length>80?2.5:4}"/></g>`;}).join('')}`;}).join('');
  return `<div class="analysis-chart" data-chart-id="${esc(id)}"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="${esc(id==='quality'?'Evolução da taxa de refugo':id==='production'?'Evolução da produção':series[0].label)}">${band}${axes}${ticks}${paths}</svg></div>${legend(series)}${limits?`<p class="analysis-range">Faixa de processo: ${num(limits[0])} a ${num(limits[1])} ${esc(unit)} · desvios em vermelho</p>`:''}`;
 }
 function bars(rows,{id,unit='peças',grouped=false}={}) {
  if(!rows.length||!rows.some(r=>r.records||r.minutes>0))return chartEmpty(id==='stops'?'Sem paradas nos filtros selecionados.':'Sem produção nos filtros selecionados.');
  const mobile=narrow(),w=mobile?380:640,left=mobile?104:160,right=mobile?32:50,top=26,rowHeight=grouped?48:40,h=top+rowHeight*rows.length+30;
  const max=Math.max(1,...rows.flatMap(r=>grouped?[r.approved,r.rejected]:[r.minutes]));
  const barWidth=v=>v/max*(w-left-right),axis=Array.from({length:3},(_,i)=>{const x=left+(w-left-right)*i/2;return `<line class="analysis-gridline" x1="${x}" x2="${x}" y1="${top-10}" y2="${h-25}"/><text x="${x}" y="${h-6}" text-anchor="middle">${esc(num(max*i/2))}</text>`;}).join('');
  const body=rows.map((r,i)=>{const y=top+i*rowHeight,text=grouped?`${r.name||r.label}\nAprovadas: ${num(r.approved)} peças\nRefugos: ${num(r.rejected)} peças${r.rejectRate!==null?'\nTaxa de refugo: '+num(r.rejectRate)+'%':''}${r.partial?'\nPeríodo em andamento.':''}`:`${r.label}\n${num(r.minutes)} min · ${r.count} registros de parada`;
   const filter=grouped&&r.kind?`data-analysis-filter="${r.kind}" data-analysis-value="${esc(r.id)}"`:'';
   const label=r.label.length>(mobile?13:23)?r.label.slice(0,mobile?12:22)+'…':r.label;
   return `<g class="analysis-target" ${tipAttrs(text+(filter?'\nClique para filtrar.':''),id+':'+(r.id??r.label))} role="button" tabindex="${i===0?'0':'-1'}" aria-label="${esc(text.replaceAll('\n','. '))}" ${filter}><rect class="analysis-hit" x="0" y="${y-10}" width="${w}" height="${rowHeight}"/><text class="analysis-category" x="${left-10}" y="${y+(grouped?13:10)}" text-anchor="end">${esc(label)}</text>${grouped? r.records?`<rect class="analysis-bar analysis-fill-0" x="${left}" y="${y}" width="${barWidth(r.approved)}" height="11" rx="2"/><rect class="analysis-bar analysis-fill-1" x="${left}" y="${y+16}" width="${barWidth(r.rejected)}" height="8" rx="2"/>`:`<text x="${left+8}" y="${y+12}" class="analysis-no-data">Sem registro</text>`:`<rect class="analysis-bar analysis-fill-2" x="${left}" y="${y}" width="${barWidth(r.minutes)}" height="16" rx="2"/>`}</g>`;}).join('');
  return `<div class="analysis-chart" data-chart-id="${id}"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="${esc(id==='stops'?'Tempo de parada por motivo':'Comparação de produção')} · ${unit}">${axis}${body}</svg></div>${grouped?legend([{label:'Aprovadas',color:0},{label:'Refugos',color:1}]):legend([{label:'Tempo de parada (min)',color:2}])}`;
 }
 function card(id,title,subtitle,body,footer='',control='') {
  charts.set(id,{title,body,footer});
  return `<section class="analysis-card" data-analysis-card="${id}"><header class="analysis-card-heading"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="analysis-expand" type="button" data-analysis-expand="${id}" aria-label="Ampliar gráfico: ${esc(title)}" title="Ampliar gráfico"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M3 3l6 6m12-6-6 6M3 21l6-6m12 6-6-6"/></svg></button></header>${control}${body}${footer?`<footer class="analysis-card-footer">${footer}</footer>`:''}</section>`;
 }
 function render(c) {
  hideTip();
  const {state,machines,availableMachines=machines,from,to,shift,sector,machineFilter}=c;
  const longRange=(new Date(to+'T12:00:00')-new Date(from+'T12:00:00'))/86400000>366;
  const names=Object.fromEntries((state.setores||MSA.config.sectors).map(s=>[s.id,s.nome]));
  const unfiltered=MSA.productionAnalysis.select(state,machines,{from,to,shift}),lots=[...new Set(['registrosProducao','leituras','perdas','paradas'].flatMap(k=>unfiltered[k].map(r=>r.lote).filter(Boolean)))].sort();
  const filters=`<div class="analysis-filters"><label class="ops-field">De<input type="date" id="ops-from" value="${from}"></label><label class="ops-field">Até<input type="date" id="ops-to" value="${to}"></label><label class="ops-field analysis-machine-filter">Máquina<select id="ops-machine"><option value="">Todas as máquinas</option>${availableMachines.map(m=>`<option value="${esc(m.id)}" ${m.id===machineFilter?'selected':''}>${esc(m.nome)}</option>`).join('')}</select></label><label class="ops-field">Turno<select id="ops-shift"><option value="todos">Todos os turnos</option>${MSA.shifts.definitions.map(t=>`<option value="${t.id}" ${shift===t.id?'selected':''}>${t.label}</option>`).join('')}</select></label><label class="ops-field">Lote<select id="analysis-lot"><option value="">Todos os lotes</option>${lots.map(l=>`<option value="${esc(l)}" ${lot===l?'selected':''}>${esc(l)}</option>`).join('')}${lot&&!lots.includes(lot)?`<option selected value="${esc(lot)}">${esc(lot)} · sem registros</option>`:''}</select></label></div>`;
  if(longRange){charts=new Map();return `<section class="analysis-page">${filters}${chartEmpty('Selecione um período de até 366 dias para visualizar os gráficos.')}</section>`;}
  const nextScope=JSON.stringify([sector,machineFilter,from,to,shift,lot]);if(nextScope!==scopeKey){comparisonPage=1;scopeKey=nextScope;}
  const data=MSA.productionAnalysis.select(state,machines,{from,to,shift,lot}),model=MSA.productionAnalysis.build(data),comparison=MSA.productionAnalysis.compare(data,names);
  let bins=model.bins;
  if(model.hourly){if(shift!=='todos')bins=bins.slice((Number(shift)-1)*8,Number(shift)*8);if(from===MSA.shifts.context(data.now).diaProducao){const hour=new Date(data.now).getHours(),offset=(hour+17)%24;bins=bins.filter(b=>(b.hour+17)%24<=offset);}}
  const pages=Math.max(1,Math.ceil(comparison.groups.length/8));comparisonPage=Math.min(comparisonPage,pages);const groups=comparison.groups.slice((comparisonPage-1)*8,comparisonPage*8);
  charts=new Map();
  const production=card('production','Evolução da produção',model.hourly?'Peças aprovadas por hora':'Peças aprovadas por dia',lineChart([{label:'Aprovadas',values:bins.map(b=>b.records?b.approved:null)}],bins.map(b=>b.label),{id:'production',details:bins.map(b=>`${num(b.rejected)} refugos registrados${b.partial?' · período parcial':''}`)}),'* Período parcial. Passe sobre os pontos ou toque para ver valores.');
  const quality=card('quality','Evolução da taxa de refugo',model.hourly?'Percentual por hora':'Percentual por dia',lineChart([{label:'Taxa de refugo',color:1,values:bins.map(b=>b.rejectRate)}],bins.map(b=>b.label),{id:'quality',unit:'%',details:bins.map(b=>`${num(b.rejected)} refugos / ${num(b.approved+b.rejected)} peças registradas`)}),'Refugos ÷ (aprovadas + refugos). Sem peças registradas, não há percentual.');
  const compareTitle={setor:'Produção por setor',maquina:'Produção por máquina',turno:'Produção por turno'}[comparison.kind];
  const paging=pages>1?`<nav class="analysis-pagination" aria-label="Grupos do gráfico"><button id="analysis-comparison-prev" type="button" data-analysis-page="${comparisonPage-1}" ${comparisonPage===1?'disabled':''}>Anterior</button><span>${comparisonPage} / ${pages}</span><button id="analysis-comparison-next" type="button" data-analysis-page="${comparisonPage+1}" ${comparisonPage===pages?'disabled':''}>Próximos</button></nav>`:'';
  const compareHtml=card('comparison',compareTitle,'Aprovadas e refugos · peças',bars(groups,{id:'comparison',grouped:true}),'Clique numa barra para isolar '+{setor:'o setor',maquina:'a máquina',turno:'o turno'}[comparison.kind]+'.'+paging);
  const stops=card('stops','Motivos de parada','Seis motivos com maior duração · minutos',bars(model.stops.slice(0,6),{id:'stops',unit:'min'}),'Duração recortada ao período; intervalos sobrepostos da mesma máquina não duplicam o total.');
  const machine=machines.length===1?machines[0]:null,parameters=Object.entries(machine?.parametros||{}).filter(([key])=>data.leituras.some(r=>Number.isFinite(r.valores?.[key])));
  if(!parameters.some(([key])=>key===parameterKey))parameterKey=parameters[0]?.[0]||'';
  const p=machine?.parametros?.[parameterKey];let parameterHtml='';
  if(p&&parameters.length){const points=data.leituras.filter(r=>Number.isFinite(r.valores?.[parameterKey])).sort((a,b)=>a.data-b.data).slice(-200),control=`<label class="ops-field analysis-parameter">Parâmetro<select id="analysis-parameter">${parameters.map(([key,v])=>`<option value="${esc(key)}" ${key===parameterKey?'selected':''}>${esc(v.nome)} · ${esc(v.unidade)}</option>`).join('')}</select></label>`;
   const graph=lineChart([{label:p.nome,values:points.map(r=>r.valores[parameterKey])}],points.map(r=>new Date(r.data).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+(from!==to?' · '+new Date(r.data).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}):'')),{id:'parameter',times:points.map(r=>r.data),limits:Number.isFinite(p.min)&&Number.isFinite(p.max)?[p.min,p.max]:null,unit:p.unidade,details:points.map(r=>MSA.productionAnalysis.origin(r)+' · lote '+(r.lote||'não informado')),evidence:points.map(r=>({id:r.id,key:parameterKey}))});
   parameterHtml=card('parameter','Evolução dos parâmetros',machine.nome,graph,'Até 200 leituras pontuais. Clique nos pontos vermelhos para investigar os registros próximos.',control);
  }
  refreshExpanded();
  const scope=machine?machine.nome:sector&&sector!=='todos'?names[sector]||sector:'Todos os setores';

  return `<section class="analysis-page">${filters}<div class="analysis-context"><strong>${esc(scope)}</strong><span>${model.latest?'Último registro: '+time(model.latest):'Nenhum registro no recorte'} · atualização automática</span></div><div id="analysis-content" class="analysis-chart-grid">${production}${quality}${compareHtml}${stops}${parameterHtml}</div>${!machine&&data.leituras.length?'<p class="analysis-footnote">Selecione uma máquina para incluir o gráfico de seus parâmetros.</p>':''}<details class="analysis-method"><summary>Como os gráficos usam os registros</summary><p>O dia produtivo vai das 07h às 07h seguintes. Produção é agrupada pelo fim do apontamento; refugos, pelo horário do registro. Lacunas indicam ausência de registros. Compare períodos equivalentes: horas e dias em andamento são parciais. Somar máquinas de diferentes etapas pode contar uma peça mais de uma vez. O filtro de lote exclui registros sem lote. Fotos são leituras pontuais; faixas configuradas não são limites estatísticos de CEP.</p></details></section>`;
 }
 function dataTable(headers,rows){return rows.length?`<div class="ops-table-wrap" tabindex="0"><table class="ops-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:chartEmpty('Nenhum registro próximo do desvio neste recorte.');}
 function investigate(c,id,key) {
  const data=MSA.productionAnalysis.select(c.state,c.machines,{from:c.from,to:c.to,shift:c.shift,lot}),d=MSA.productionAnalysis.build(data).deviations.find(d=>d.record.id===id&&d.key===key);
  if(!d){c.notify('Este desvio não está disponível nos filtros atuais.',true);return;}
  hideTip();const e=MSA.productionAnalysis.evidence(data,d),rows=[...e.production.map(r=>['Produção',r,`${num(r.quantidade)} peças aprovadas · ${time(r.inicio)} a ${time(r.fim)}`]),...e.losses.map(r=>['Qualidade',r,`${num(r.quantidade)} ${r.unidade==='kg'?'kg':'peças'} · ${r.motivo||r.tipo}`]),...e.stops.map(r=>['Parada',r,`${r.motivo||'Sem motivo'} · ${r.fim?'encerrada':'em andamento'}`]),...e.occurrences.map(r=>['Ocorrência',r,r.descricao||''])].sort((a,b)=>MSA.productionAnalysis.stamp(a[1])-MSA.productionAnalysis.stamp(b[1]));
  c.open('Investigar · '+d.parameter.nome,`<section class="full"><p><strong>${esc(d.machine.nome)} · ${esc(d.record.lote||'Sem lote')}</strong></p><p>${time(d.record.data)} · ${num(d.value)} ${esc(d.parameter.unidade)} · ${esc(MSA.productionAnalysis.origin(d.record))}</p><p class="ops-note">Janela: ${time(e.start)} a ${time(e.end)}, limitada aos filtros. Intervalos de produção são mostrados completos.</p>${dataTable(['Tipo / horário','Registro','Lote'],rows.map(([type,r,text])=>[`${esc(type)}<small>${esc(time(r.inicio||r.data))}</small>`,esc(text),esc(r.lote||'Sem lote · contexto da máquina')]))}<p class="ops-note">A proximidade de horários não comprova causalidade. Confirme a causa com a operação.</p><a class="secondary-button" href="#maquinas/${encodeURIComponent(d.machine.id)}">Abrir máquina</a></section>`,null);
 }
 function expand(c,id){const chart=charts.get(id);if(!chart)return;hideTip();c.open(chart.title,`<section class="full analysis-expanded">${chart.body}<div class="ops-note">${chart.footer.replace(/<nav[\s\S]*<\/nav>/,'')}</div></section>`,null);const dialog=document.querySelector('#operation-dialog');dialog.dataset.analysisChart=id;dialog.classList.add('analysis-chart-dialog');}
 function refreshExpanded(){const dialog=document.querySelector('#operation-dialog');if(!dialog?.open||!dialog.classList.contains('analysis-chart-dialog'))return;const chart=charts.get(dialog.dataset.analysisChart),body=dialog.querySelector('.analysis-expanded');if(!chart||!body)return;const point=body.contains(document.activeElement)?document.activeElement.dataset.analysisPoint:null;body.innerHTML=chart.body+`<div class="ops-note">${chart.footer.replace(/<nav[\s\S]*<\/nav>/,'')}</div>`;dialog.querySelector('#operation-dialog-title').textContent=chart.title;if(point){const next=[...body.querySelectorAll('[data-analysis-point]')].find(p=>p.dataset.analysisPoint===point);next?.focus({preventScroll:true});}}
 const tooltip=document.createElement('div');tooltip.className='analysis-tooltip';tooltip.id='analysis-tooltip';tooltip.hidden=true;tooltip.setAttribute('role','status');tooltip.innerHTML='<button type="button" aria-label="Fechar valor do gráfico">×</button><div></div>';document.body.append(tooltip);
 let tipTarget=null;
 function hideTip(){if(tooltip.parentNode!==document.body)document.body.append(tooltip);if(tipTarget)tipTarget.removeAttribute('aria-describedby');tipTarget=null;tooltip.hidden=true;}
 function showTip(target,event){if(!target?.isConnected)return;tipTarget?.removeAttribute('aria-describedby');tipTarget=target;const parent=target.closest('dialog')||document.body;if(tooltip.parentNode!==parent)parent.append(tooltip);target.setAttribute('aria-describedby',tooltip.id);tooltip.querySelector('div').textContent=target.dataset.analysisTip;tooltip.hidden=false;const r=target.getBoundingClientRect(),x=event?.clientX||r.left+r.width/2,y=event?.clientY||r.top+r.height/2;tooltip.style.left=Math.max(12,Math.min(innerWidth-tooltip.offsetWidth-12,x+12))+'px';tooltip.style.top=Math.max(12,y+16+tooltip.offsetHeight>innerHeight?y-tooltip.offsetHeight-12:y+16)+'px';}
 tooltip.querySelector('button').addEventListener('click',hideTip);
 document.addEventListener('pointerover',e=>{const t=e.target.closest('[data-analysis-tip]');if(t)showTip(t,e);});
 document.addEventListener('pointerout',e=>{const t=e.target.closest('[data-analysis-tip]');if(t&&!t.contains(e.relatedTarget)&&!tooltip.contains(e.relatedTarget)&&document.activeElement!==t)hideTip();});
 document.addEventListener('focusin',e=>{const t=e.target.closest('[data-analysis-tip]');if(t)showTip(t);else if(!tooltip.contains(e.target))hideTip();});
 document.addEventListener('click',e=>{const t=e.target.closest('[data-analysis-tip]');const modal=document.querySelector('dialog[open]');if(t&&(!modal||modal.contains(t)))showTip(t,e);else if(!tooltip.contains(e.target))hideTip();});
 document.addEventListener('scroll',hideTip,true);
 window.addEventListener('hashchange',hideTip);
 document.addEventListener('close',e=>{if(e.target.id==='operation-dialog'&&e.target.classList.contains('analysis-chart-dialog')){const id=e.target.dataset.analysisChart;requestAnimationFrame(()=>document.querySelector('.analysis-page [data-analysis-expand="'+id+'"]')?.focus({preventScroll:true}));}},true);
 document.addEventListener('keydown',e=>{const t=e.target.closest('[data-analysis-tip]');if(!t)return;if(e.key==='Escape'){hideTip();return;}if(['Enter',' '].includes(e.key)){e.preventDefault();t.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const points=[...t.closest('svg').querySelectorAll('[data-analysis-tip]')],i=points.indexOf(t),next=e.key==='Home'?0:e.key==='End'?points.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+points.length)%points.length;points.forEach(p=>p.setAttribute('tabindex','-1'));points[next].setAttribute('tabindex','0');points[next].focus();});
 MSA.analysisUI={render,investigate,expand,hideTip,change(id,value){if(id==='analysis-lot')lot=value;if(id==='analysis-parameter')parameterKey=value;},setPage(value){if(Number.isInteger(Number(value))&&Number(value)>0)comparisonPage=Number(value);},get key(){return [lot,parameterKey,comparisonPage];}};
})();
